    @jax.jit
    def rl_step(params, state, key):
        k_p, k_s = jax.random.split(key)
        prompts = jnp.repeat(make_prompts(k_p, prompts_per_step), group, 0)
        sampler = jax.tree.map(jnp.add, params, delta)
        tokens, tok_lp, vocab_lp = generate(k_s, sampler, prompts)
        r = rewards(tokens)
        if reward_mode == "group_centered":
            adv = r.reshape(-1, group)
            adv = (adv - adv.mean(1, keepdims=True)).reshape(-1)
        elif reward_mode == "plus_minus":
            adv = 2 * r - 1
        else:
            raise ValueError(reward_mode)
        mask = completion_mask(B)
        batch = {"tokens": tokens, "mask": mask, "advantages": adv, "sampling_token_logprobs": tok_lp}
        top_lp, top_ids = jax.lax.top_k(vocab_lp, min(SAMPLER_TOPK, VOCAB))
        batch |= {"sampler_topk_ids": top_ids, "sampler_topk_logprobs": top_lp}

        def objective(params):
            return loss_fn(forward(params, tokens), lambda x: head(params, x), batch)

        (loss, metrics), grads = jax.value_and_grad(objective, has_aux=True)(params)
        updates, state = opt.update(grads, state, params)
        params = optax.apply_updates(params, updates)
    """Compress the final partial chunk and trim the padding. Rows past an
    early stop hold stale values; consumers mask them."""
    head_logprobs, head_ids = _topk_compress(carry.ring, carry.head_logprobs, carry.head_ids, position // _TOPK_CHUNK * _TOPK_CHUNK)
    return head_logprobs[:, :seq_len], head_ids[:, :seq_len]


def _topk_compress(ring, head_logprobs, head_ids, start):
    k = head_logprobs.shape[-1]

    def local_topk(block):
        values, ids = jax.lax.top_k(block, k, is_stable=False)
        return values, ids + jax.lax.axis_index("model") * block.shape[-1]

    spec = P("data", None, "model")
    values, ids = jax.shard_map(local_topk, in_specs=spec, out_specs=(spec, spec))(ring)
    rows = P(("data", "model"), None, None)
    values, ids = reshard(values, rows), reshard(ids, rows)
    top_logprobs, idx = jax.lax.top_k(values, k, is_stable=False)
    top_ids = jnp.take_along_axis(ids, idx, axis=-1)
    return (jax.lax.dynamic_update_slice(head_logprobs, top_logprobs, (0, start, 0)),
            jax.lax.dynamic_update_slice(head_ids, top_ids, (0, start, 0)))
